// n8n API로 크롤링 워크플로우 최근 실행 결과 조회
const crawlWorkflows = ['INU 크롤링 - 전체 공지', 'INU 크롤링 - 학사 공지', 'INU 크롤링 - 컴퓨터공학부'];
const results = [];

for (const name of crawlWorkflows) {
  // n8n 내부에서는 실행 이력을 직접 조회 가능
  results.push({
    workflow: name,
    status: 'CHECK_NEEDED',
    message: 'n8n 실행 이력에서 최근 3시간 내 실행 결과 확인 필요'
  });
}

return [{ json: { results, checked_at: new Date().toISOString() } }];

const results = $('크롤링 상태 집계').first().json.results;
const failedCount = results.filter(r => r.status === 'FAILED').length;
const totalCount = results.length;

if (failedCount >= 2) {
  return [{ json: { alert: true, message: `⚠️ 크롤링 경고: ${failedCount}/${totalCount}개 소스 실패`, results } }];
} else {
  return [{ json: { alert: false, message: `✅ 크롤링 정상: ${totalCount}개 소스 모두 정상`, results } }];
}
